function planForm(id,key='',duplicate=false) {
  const existing=state().plans.find(p=>p.id===id),session=key?sessionFromKey(key):null;
  let p=existing||{classId:session?.classId||ui.planClass||state().classes[0]?.id,date:session?.date||ui.planDate,periodId:session?.periodId||'',title:'',objective:'',activities:'',resources:''};
  if(!p.classId)return toast('Create a class first.',true);
  if(duplicate)p={...p,date:ui.planDate,title:p.title+' (copy)'};
  if(!p.periodId)p={...p,periodId:D.sessionsOn(state(),p.date).find(l=>l.classId===p.classId)?.periodId||''};
  openDialog(duplicate?'Duplicate lesson plan':existing?'Edit lesson plan':'Plan a lesson',form('plan',duplicate?'':id,`<div class="form-grid"><label class="field">Class<select id="plan-form-class" name="classId">${classOptions(p.classId)}</select></label>${field('Lesson date','date',p.date,'date','required id="plan-form-date"')}<label class="field full">Timetabled session<select id="plan-form-period" name="periodId">${planPeriodOptions(p.classId,p.date,p.periodId,existing)}</select></label>${field('Lesson title','title',p.title,'text','required maxlength="200"')}${area('Learning intention','objective',p.objective,'full')}${area('Lesson sequence & activities','activities',p.activities,'full')}${area('Resources & preparation','resources',p.resources,'full')}</div><p class="form-hint">New plans link to a specific timetabled class and period. One saved plan is allowed per class session.</p>`),true);
}
function planView(id) {
  const p=state().plans.find(p=>p.id===id);if(!p)return;
  openDialog(p.title,`<p class="form-hint">${esc(byClass(p.classId).name)} · ${esc(fmt(p.date))} · ${esc(D.periodAt(state(),p.periodId)?.name||'Legacy plan')}</p>${[['Learning intention',p.objective],['Lesson sequence & activities',p.activities],['Resources & preparation',p.resources]].map(([t,v])=>`<div class="profile-section"><h3>${t}</h3><p>${esc(v)||'Not added yet.'}</p></div>`).join('')}<div class="dialog-actions">${button('Delete plan','delete-plan',p.id,'danger','trash')}${button('Duplicate','duplicate-plan',p.id,'','plus')}${button('Edit lesson','edit-plan',p.id,'primary','edit')}</div>`,true);
}
function settingsPageV2() {
  const s=state(),years=[...s.calendar.years].sort((a,b)=>a.start.localeCompare(b.start)),terms=[...s.calendar.terms].sort((a,b)=>a.start.localeCompare(b.start));
  const rowTools=(kind,id)=>`<span class="inline-actions">${button('Edit','edit-'+kind,id,'small','edit')}${button('Remove','delete-'+kind,id,'small danger','trash')}</span>`;
  return heading('Make it yours','Settings & school calendar','Your colours, teaching dates, periods and one-day timetable changes.')+
    `<div class="settings-grid"><div><section class="settings-card"><h2>Workspace & colours</h2><p>Choose a colour scheme and personalise the teaching workspace.</p><form data-form="settings"><div class="form-error" role="alert"></div>${field('School name','school',s.settings.school,'text','required maxlength="200"')}${field('Your display name','teacher',s.settings.teacher,'text','required maxlength="200"')}${field('Your role','role',s.settings.role,'text','required maxlength="200"')}${selectField('Colour scheme','theme',Object.entries(D.THEMES).map(([id,name])=>opt(id,name,s.settings.theme)).join(''))}<div class="theme-swatches" aria-hidden="true">${Object.keys(D.THEMES).map(t=>`<span class="swatch ${t}"></span>`).join('')}</div><button type="submit" class="button primary">${icon('save')}Save workspace</button></form></section>
    <section class="settings-card"><div class="section-heading"><h2>School years</h2>${button('Add year','new-year','','small','plus')}</div><p>These are editable demonstration dates. Set the school calendar before taking attendance.</p>${years.map(y=>`<div class="calendar-row"><div><strong>${esc(y.name)}</strong><small>${esc(fmt(y.start))} – ${esc(fmt(y.end))}</small></div>${rowTools('year',y.id)}</div>`).join('')||'<p>No school years configured.</p>'}</section>
    <section class="settings-card"><div class="section-heading"><h2>School terms</h2>${button('Add term','new-term','','small','plus')}</div><p>Term boundaries define the attendance grid and week numbers. Dates inside a school year but outside its terms are School Holidays.</p>${terms.map(t=>`<div class="calendar-row"><div><strong>${esc(s.calendar.years.find(y=>y.id===t.yearId).name)} · ${esc(t.name)}</strong><small>${esc(fmt(t.start))} – ${esc(fmt(t.end))}</small></div>${rowTools('term',t.id)}</div>`).join('')||'<p>No school terms configured.</p>'}</section></div>
    <div><section class="settings-card"><div class="section-heading"><h2>School & public holidays</h2>${button('Add holiday','new-holiday','','small','plus')}</div><p>Classes and lesson-plan entries are replaced with School Holidays or Public Holiday. Public holidays take priority when dates overlap.</p>${[...s.calendar.holidays].sort((a,b)=>a.start.localeCompare(b.start)).map(h=>`<div class="calendar-row"><div><strong>${esc(h.name)}</strong><small>${esc(h.type)} · ${esc(fmt(h.start))} – ${esc(fmt(h.end))}</small></div>${rowTools('holiday',h.id)}</div>`).join('')||'<p class="subtle">No additional holidays recorded. Gaps between terms already count as school holidays.</p>'}</section>
    <section class="settings-card"><div class="section-heading"><h2>Special Timetable</h2>${button('Add date','new-special','','small','plus')}</div><p>Replace the regular classes for one date. Other days and future recurring classes keep their usual timetable. Calendar closures still take priority.</p>${[...s.specialDays].sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<div class="calendar-row"><div><strong>${esc(d.label)}</strong><small>${esc(fmt(d.date))} · ${d.sessions.length} sessions</small></div>${rowTools('special',d.id)}</div>`).join('')||'<p>No special timetable dates recorded.</p>'}</section>
    <section class="settings-card"><h2>Timetable periods</h2><p>Set the start and end times for the nine periods. Recess and lunch remain breaks.</p><form data-form="periods"><div class="form-error" role="alert"></div><div class="period-editor">${s.periods.map(p=>`<div><strong>${esc(p.name)}</strong><label>Start<input name="start_${p.id}" aria-label="${p.name} start" type="time" required value="${p.start}"></label><label>End<input name="end_${p.id}" aria-label="${p.name} end" type="time" required value="${p.end}"></label></div>`).join('')}</div><button class="button primary" type="submit">${icon('save')}Save period times</button></form></section></div></div>
    <div class="settings-grid"><section class="settings-card"><h2>Backup & restore</h2><p>Saved data stays in this browser. Download a JSON backup before clearing storage. Version 1 and 2 backups are upgraded automatically when restored.</p>${button('Download backup','backup','','primary','download')}${button('Restore backup','restore','','','upload')}${store.blocked?'<hr>'+button('Export original saved data','export-original','','','download'):''}</section><section class="settings-card"><h2>About version 3.0</h2><p>This is a single-user prototype with fictional records, no staff login and no shared database. SchoolDesk is independent of SEQTA and Tes.</p><p>Overall grades: A ≥75%, B ≥65%, C ≥50%, D ≥35%, E ≥15%, F below 15%. Blank tasks are excluded from overall marks.</p>${button('Reset demo data','reset','','danger','trash')}</section></div>`;
}
function calendarForm(kind,id) {
  const list=kind==='year'?'years':kind==='term'?'terms':'holidays',old=state().calendar[list].find(x=>x.id===id),y=state().calendar.years[0];
  if(kind==='term'&&!y)return toast('Add a school year first.',true);
  const x=old||{name:kind==='year'?String(Number(today.slice(0,4))+1):kind==='term'?'Term 1':'',start:kind==='term'?y.start:today,end:kind==='term'?y.end:today,yearId:y?.id,type:'School Holidays'};
  openDialog((id?'Edit ':'Add ')+(kind==='year'?'school year':kind==='term'?'school term':'holiday'),form(kind,id,`<div class="form-grid">${field('Name','name',x.name,'text','required maxlength="200"')}${kind==='term'?selectField('School year','yearId',yearOptions(x.yearId)):''}${kind==='holiday'?selectField('Type','type',['School Holidays','Public Holiday'].map(t=>opt(t,t,x.type)).join('')):''}${field('Start date','start',x.start,'date','required')}${field('End date','end',x.end,'date','required')}</div><p class="form-hint">Start and end dates are inclusive. School years and terms cannot overlap.</p>`));
}
function specialForm(id,date=today,copyRegular=false) {
  const old=state().specialDays.find(d=>d.id===id)||state().specialDays.find(d=>d.date===date),selected=old?.date||date;
  const sessions=copyRegular?D.recurringOn(state(),selected).filter(l=>l.day===new Date(selected+'T12:00:00').getDay()):old?.sessions||[];
  openDialog('Special Timetable',form('special',old?.id||'',`<div class="form-grid">${field('Date','date',selected,'date','required id="special-form-date"')}${field('Name / event','label',old?.label||'Special Timetable','text','required maxlength="200"')}</div><p class="form-hint">This replaces all recurring sessions for the selected date only. Leave a period empty for no class. School event entries can have a title without a class roster.</p>${button('Copy regular timetable','copy-regular-special','','small','calendar')}<div class="special-editor">${teachingPeriods().map(p=>{const l=sessions.find(l=>l.periodId===p.id),value=l?.classId||(l?'__event':'');return `<div><h3>${p.name}<small>${p.start}–${p.end}</small></h3><label class="field">Class or event<select name="class_${p.id}">${opt('','No class',value)}${opt('__event','School event (no class roster)',value)}${classOptions(value)}</select></label>${field('Title (required for an event)','title_'+p.id,l?.title||'','text','maxlength="200"')}${field('Room','room_'+p.id,l?.room||'','text','maxlength="100"')}</div>`;}).join('')}</div>`),true);
}
function saveV2Form(kind,fd,id) {
  const read=name=>String(fd.get(name)||'').trim();
  if(['year','term','holiday'].includes(kind)){
    const key=kind==='year'?'years':kind==='term'?'terms':'holidays',x={id:id||D.uid(kind),name:read('name'),start:read('start'),end:read('end')};
    if(kind==='term')x.yearId=read('yearId');if(kind==='holiday')x.type=read('type');
    commit(s=>{const i=s.calendar[key].findIndex(x=>x.id===id);if(i<0)s.calendar[key].push(x);else s.calendar[key][i]=x;},'School calendar saved.');return true;
  }
  if(kind==='periods'){
    commit(s=>{s.periods=s.periods.map(p=>({...p,start:read('start_'+p.id),end:read('end_'+p.id)}));},'Timetable period times saved.');return true;
  }
  if(kind==='special'){
    const sessions=[];
    for(const p of teachingPeriods()){const value=read('class_'+p.id);if(!value)continue;sessions.push({id:'sp_'+p.id,periodId:p.id,classId:value==='__event'?'':value,title:read('title_'+p.id),room:read('room_'+p.id)});}
    const x={id:id||D.uid('special'),date:read('date'),label:read('label'),sessions};
    commit(s=>{const i=s.specialDays.findIndex(x=>x.id===id);if(i<0)s.specialDays.push(x);else s.specialDays[i]=x;},'Special Timetable saved for this date only.');return true;
  }
  if(kind==='absence'){
    const x={id:id||D.uid('absence'),studentId:read('studentId'),type:read('type'),start:read('start'),end:read('end'),periodIds:fd.getAll('periodIds'),comment:read('comment')};
    commit(s=>{const i=s.absences.findIndex(a=>a.id===id);if(i<0)s.absences.push(x);else s.absences[i]=x;},'Student attendance saved.');ui.absenceStudent=x.studentId;return true;
  }
  return false;
}
function deleteCalendar(kind,id) {
  if(!window.confirm('Remove this '+kind+'? Saved attendance and lesson plans will be retained, even if no longer timetabled.'))return;
  commit(s=>{
    if(kind==='special')s.specialDays=s.specialDays.filter(x=>x.id!==id);
    else {const key=kind==='year'?'years':kind==='term'?'terms':'holidays';if(kind==='year'&&(s.calendar.terms.some(t=>t.yearId===id)||s.assessments.some(a=>a.yearId===id)))throw new Error('Remove this year’s terms and move or remove its assessments before removing the school year.');s.calendar[key]=s.calendar[key].filter(x=>x.id!==id);}
  },'Calendar updated.');render();
}
function exportOriginal() {
  const raw=store.storage?.getItem(D.STORAGE_KEY);if(!raw)return toast('No original saved data found.',true);
  download('schooldesk-original-saved-data.json',raw,'application/json');
}

const classStyle=c=>`--class-colour:${D.PALETTE[c?.colour]||D.PALETTE.sage}`;
function studentForm(id){
 const x=byStudent(id)||{firstName:'',lastName:'',preferredName:'',year:'9',homegroup:'',guardian:'',email:'',phone:'',support:'',schoolEnrolments:[{start:today,end:''}]};
 openDialog(id?'Edit student':'Add a student',form('student',id,`<div class="form-grid">${field('First name','firstName',x.firstName,'text','required maxlength="100"')}${field('Last name','lastName',x.lastName,'text','required maxlength="100"')}${field('Preferred name (optional)','preferredName',x.preferredName,'text','maxlength="100"')}${field('Student number','code',x.code||'Generated automatically on save','text','readonly')}${selectField('Year level','year',Array.from({length:13},(_,i)=>opt(i,String(i),x.year)).join(''))}${field('Homegroup','homegroup',x.homegroup,'text','required maxlength="100"')}${!id||x.schoolEnrolments.length?field('First school enrolment date','schoolStart',x.schoolEnrolments[0]?.start||today,'date','required'):''}${field('Parent / caregiver','guardian',x.guardian,'text','maxlength="200"')}${field('Contact email','email',x.email,'email','maxlength="200"')}${field('Phone','phone',x.phone,'tel','maxlength="100"')}${area('Learning support notes','support',x.support,'full')}</div><p class="form-hint">Student numbers are unique, automatic and never changed on edit. Use Archive / Re-enrol from the student profile to set an effective withdrawal or return date.</p>`));
}
function studentLifecycleSection(id){
 const x=byStudent(id),enrolled=D.studentEnrolled(x,today),entries=D.attendanceEntries(state(),{studentId:id,end:today}),tasks=state().assessments.filter(a=>a.marks[id]!==undefined||a.statuses[id]),open=state().notes.filter(n=>n.studentId===id&&n.status==='Open');
 return `<section class="profile-section"><h3>School enrolment</h3>${x.schoolEnrolments.map(r=>`<div class="mini-row"><span>${esc(fmt(r.start))}</span><span>${r.end?'First day no longer enrolled: '+esc(fmt(r.end)):'Currently open'}</span></div>`).join('')||'<p>No active school enrolment.</p>'}<div class="inline-actions" style="margin-top:14px">${button(enrolled?'Archive student':'Re-enrol student',enrolled?'archive-student':'restore-student',id,enrolled?'danger small':'primary small','calendar')}</div></section><section class="profile-section"><h3>Class enrolment dates</h3>${state().classes.flatMap(c=>c.enrolments.filter(e=>e.studentId===id).map(e=>`<div class="mini-row"><span>${esc(c.code)}</span><span>${esc(fmt(e.start))} → ${e.end?esc(fmt(e.end))+' (first day out)':'Open'}</span></div>`)).join('')||'<p>No class enrolments recorded.</p>'}</section><section class="profile-section"><h3>Student progress</h3><p>${entries.length} recorded lesson entries · ${tasks.length} assessed tasks · ${open.length} open follow-ups</p><div class="progress-results">${tasks.map(a=>{const v=D.assessedValue(a,id);return `<div class="mini-row"><span>${esc(a.title)}<small class="subtle"> · ${esc(fmt(a.due))}</small></span><strong>${v===null?esc(D.assessmentStatus(a,id)):pct(v/a.max*100)+' · '+D.grade(v,a.max)}</strong></div>`;}).join('')}</div><h3 style="margin-top:22px">Attendance history</h3><div class="student-timeline">${[...entries].reverse().slice(0,100).map(e=>`<div class="mini-row"><span>${esc(fmt(e.date))} · ${esc(byClass(e.classId).code)} · ${esc(D.periodAt(state(),e.periodId)?.name||e.session)}</span><span>${statusIcon(e.status)} ${esc(e.status)}</span></div>`).join('')||'<p>No attendance recorded through today.</p>'}</div><p class="form-hint">Attendance history shows the latest 100 entries; CSV exports contain all saved entries. Assessments are listed in the order they were created.</p></section>`;
}
function lifecycleForm(kind,id){
 const student=kind.includes('student'),x=student?byStudent(id):byClass(id),restore=kind.startsWith('restore');
 openDialog((restore?'Restore / re-enrol ':'Archive ')+(student?fullName(x):x.name),form('lifecycle',id,`<input name="kind" type="hidden" value="${kind}">${field(restore?'First day enrolled / active again':'Effective date — first day no longer enrolled / active','date',today,'date','required')}<p class="form-hint">${student?(restore?'This starts a new school enrolment. Add the student to the required class rosters separately.':'From this date the student is no longer enrolled in school or any class. Earlier records remain intact.'):(restore?'This reactivates the class from the selected date. Earlier archived dates stay archived.':'This hides the class from active lists and stops scheduled lessons from this date. Earlier attendance, marks and lesson plans remain available.')}</p>`));
}
function classesPage(){
 const archived=c=>c.archivePeriods.some(r=>r.start<=today&&(!r.end||today<r.end)),filter=ui.classStatus||'Active',list=state().classes.filter(c=>filter==='All'||!archived(c)===(filter==='Active'));
 return heading('Your teaching groups','My classes','Dated rosters, archived history and a colour for every class.',button('Create class','new-class','','primary','plus'))+`<div class="toolbar"><select id="class-status" aria-label="Class status">${['Active','Archived','All'].map(x=>opt(x,x,filter)).join('')}</select><span class="subtle">${list.length} classes</span></div><div class="cards-grid">${list.map(c=>`<article class="class-card"><div class="class-banner ${c.colour}" style="${classStyle(c)}"><div class="class-code">${esc(c.code)} · ${esc(state().calendar.years.find(y=>y.id===c.yearId)?.name||'Legacy years')}</div><h2>${esc(c.name)}</h2></div><div class="class-body"><div class="class-meta"><span>${roster(c).length} enrolled now</span><span>Room ${esc(c.room)||'—'}</span></div><div class="class-actions">${button('Attendance','class-roll',c.id,'small')}${button('Marksbook','class-marks',c.id,'small')}${button('Edit roster','edit-class',c.id,'small','edit')}${button(!archived(c)?'Archive':'Restore',!archived(c)?'archive-class':'restore-class',c.id,'small',!archived(c)?'trash':'arrow')}</div></div></article>`).join('')}</div>${!list.length?empty('No classes in this view','Change the status filter or create a class.'):''}`;
}
function classForm(id){
 if($('dialog').open&&ui.formDirty&&!discard())return;
 const c=byClass(id)||{name:'',code:'',year:'9',room:'',colour:'sage',yearId:D.yearAt(state(),today)?.id||state().calendar.years[0]?.id||'',enrolments:[],studentIds:[]};
 ui.rosterEditing=id||'';ui.rosterEnrolments=D.clone(c.enrolments);ui.rosterSelected=new Set(c.enrolments.filter(r=>!r.end||r.end>today).map(r=>r.studentId));ui.rosterFilters={search:'',year:'',group:'',status:'Active'};ui.rosterDate=today;
 openDialog(id?'Edit class & dated roster':'Create a class',form('class',id,`<div class="form-grid">${field('Class name','name',c.name,'text','required maxlength="100"')}${field('Class code','code',c.code,'text','required maxlength="30"')}${field('Year level','year',c.year,'number','required min="0" max="12" step="1"')}${selectField('School year','yearId',(id&&!c.yearId?opt('','Legacy — all configured years',''):'')+yearOptions(c.yearId))}${field('Default room','room',c.room,'text','maxlength="100"')}${field('Roster changes effective from','membershipDate',today,'date','required id="membership-date"')}</div><label class="field">Class colour<input name="colour" id="selected-class-colour" type="hidden" value="${c.colour}"><span id="colour-current" class="colour-current" style="background:${D.PALETTE[c.colour]}">Selected colour</span></label><div class="colour-picker" role="group" aria-label="Class colour">${Object.entries(D.PALETTE).map(([key,hex])=>`<button type="button" class="colour-swatch ${key===c.colour?'selected':''}" data-action="pick-class-colour" data-id="${key}" style="background:${hex}" aria-label="Colour ${hex}" aria-pressed="${key===c.colour}"></button>`).join('')}</div><h3>Student roster</h3><p class="form-hint">Filters do not clear selected students. End dates are the first day no longer enrolled. Unchecking a student ends their current membership from the effective date; earlier history is kept.</p><div class="roster-filters"><input id="roster-search" aria-label="Search roster students" placeholder="Name or student number"><select id="roster-year" aria-label="Roster year level">${opt('','All year levels','')}${[...new Set(state().students.map(s=>s.year))].sort().map(y=>opt(y,'Year '+y,'')).join('')}</select><select id="roster-group" aria-label="Roster homegroup">${opt('','All homegroups','')}${[...new Set(state().students.map(s=>s.homegroup))].sort().map(g=>opt(g,g,'')).join('')}</select><select id="roster-status" aria-label="Roster student status">${['Active','Archived','All'].map(x=>opt(x,x,'Active')).join('')}</select></div><div id="roster-choices" class="roster-list">${rosterChoices()}</div><div id="selected-roster">${selectedRoster()}</div>`),true);
}
function rosterChoices(){
 const f=ui.rosterFilters,list=state().students.filter(s=>(f.status==='All'||D.studentEnrolled(s,ui.rosterDate)===(f.status==='Active'))&&(!f.year||s.year===f.year)&&(!f.group||s.homegroup===f.group)&&`${fullName(s)} ${s.code}`.toLowerCase().includes(f.search.toLowerCase()));
 return list.map(s=>`<label><input type="checkbox" data-roster-student="${s.id}" value="${s.id}"${ui.rosterSelected.has(s.id)?' checked':''}><span>${esc(fullName(s))}<small class="subtle"> · ${esc(s.year)} · ${esc(s.homegroup)}</small></span></label>`).join('')||'<p class="subtle">No matching students.</p>';
}
function selectedRoster(){
 return `<h3 style="margin:18px 0 10px">${ui.rosterSelected.size} selected students</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>First day enrolled</th><th>First day no longer enrolled</th></tr></thead><tbody>${[...ui.rosterSelected].map(id=>{const s=byStudent(id),e=[...ui.rosterEnrolments].reverse().find(e=>e.studentId===id)||{start:ui.rosterDate,end:''};return `<tr><td>${esc(fullName(s))}</td><td><input type="date" data-member-start="${id}" value="${e.start}" aria-label="${esc(fullName(s))} enrolment start"></td><td><input type="date" data-member-end="${id}" value="${e.end}" aria-label="${esc(fullName(s))} first day out"></td></tr>`;}).join('')}</tbody></table></div><details><summary>Previous class memberships</summary>${ui.rosterEnrolments.filter(e=>e.end&&e.end<=ui.rosterDate).map(e=>`<p class="subtle">${esc(fullName(byStudent(e.studentId)))} · ${esc(e.start)} → ${esc(e.end)} (first day out)</p>`).join('')||'<p class="subtle">No ended memberships.</p>'}</details>`;
}
function membershipFor(id,rejoining=false){let r=[...ui.rosterEnrolments].reverse().find(r=>r.studentId===id&&(!rejoining||!r.end||r.end>ui.rosterDate));if(!r){r={studentId:id,start:ui.rosterDate,end:''};ui.rosterEnrolments.push(r);}return r;}
function collectEnrolments(){
 const rows=D.clone(ui.rosterEnrolments);
 return rows.flatMap(e=>{if(ui.rosterSelected.has(e.studentId)||e.end&&e.end<=ui.rosterDate)return[e];if(e.start>=ui.rosterDate)return[];return[{...e,end:ui.rosterDate}];});
}
function lessonForm(id){
 const reference=ui.sessionContextDate||today,list=D.recurringOn(state(),reference),l=list.find(l=>l.id===id)||{classId:state().classes.find(c=>D.classAvailable(state(),c,today))?.id,day:1,periodId:'p1',room:''},c=byClass(l.classId);
 if(!state().classes.length)return toast('Create a class first.',true);
 openDialog(id?'Edit recurring class':'Add a recurring class',form('lesson',id,`<input name="sourceDate" type="hidden" value="${reference}"><div class="form-grid">${selectField('Class','classId',classOptions(l.classId))}${selectField('Day of week','day',['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>opt(i+1,d,l.day)).join(''))}${selectField('Period','periodId',teachingPeriods().map(p=>opt(p.id,p.name+' · '+p.start+'–'+p.end,l.periodId)).join(''))}${field('Room','room',l.room||c?.room||'','text','maxlength="100" data-default-room="true" '+(id&&l.room!==c?.room?'data-overridden="true"':''))}${field('Effective from','effectiveFrom',today,'date','required')}</div><p class="form-hint">Earlier dates keep their previous timetable. This version applies until the next scheduled timetable change. The class default room is pre-filled; you can override it.</p>${id?button('Remove from an effective date','remove-recurring',id,'danger small','trash'):''}`));
}
function attendanceStudents(sessions){
 const term=currentAttendanceTerm(),c=byClass(ui.rollClass),ids=new Set();if(c&&term)for(const e of c.enrolments)if(e.start<=term.end&&(!e.end||e.end>term.start))ids.add(e.studentId);
 for(const l of sessions)Object.keys(state().attendance.find(r=>r.id===l.key)?.rows||{}).forEach(id=>ids.add(id));return [...ids].map(byStudent).filter(Boolean).sort((a,b)=>a.lastName.localeCompare(b.lastName));
}
function attendanceCell(l,s){
 const v=D.attendanceValue(state(),l,s.id,ui.rollDraft),title=v.status||'Unmarked',editable=!v.locked;
 return `<td class="attendance-cell ${v.notEnrolled?'not-enrolled':''} ${l.date===ui.rollDate?'selected-lesson':''}"><button type="button" class="attendance-square ${v.locked?'locked':''}" data-action="attendance-cell" data-id="${s.id}" data-session="${l.key}" title="${esc(title)}" aria-label="${esc(fullName(s)+' · '+fmt(l.date)+' · '+l.periodName+' · '+title)}" aria-disabled="${!editable}"${editable?'':' data-locked="true"'}>${v.notEnrolled?'<span class="not-enrolled-fill" aria-hidden="true"></span>':statusIcon(v.status)}</button></td>`;
}
function statusIcon(status){
 if(!status||status==='Not enrolled')return '<span class="unmarked-dot" aria-hidden="true"></span>';
 const tick='<path d="m3 11 6 6L21 5" fill="none" stroke="#173c52" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="m3 11 6 6L21 5" fill="none" stroke="#2a9ed2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>',cross='<path d="m5 5 14 14M19 5 5 19" stroke="#702521" stroke-width="5"/><path d="m5 5 14 14M19 5 5 19" stroke="#e0322a" stroke-width="3"/>';
 let draw=status==='Absent'?cross:tick;
 const badge=(text,fill='#477c2e')=>`<rect x="12" y="12" width="12" height="12" rx="2" fill="#fff"/><text x="18" y="22" text-anchor="middle" font-family="Arial,sans-serif" font-size="11" font-weight="bold" fill="${fill}">${text}</text>`;
 if(status==='Late')draw+=badge('L');
 else if(status==='Late/Medical')draw='<rect x="2" y="2" width="16" height="17" rx="2" fill="#fff" stroke="#3c4a4d" stroke-width="1.5"/><path d="M6 6h8M6 10h7" stroke="#65757b"/>'+badge('L','#bb332c');
 else if(status==='Medical')draw='<rect x="2" y="2" width="19" height="20" rx="2" fill="#fff" stroke="#414a4b" stroke-width="1.5"/><path d="M7 7h10v5H7zM10 4h5v12h-5z" fill="#c7352f"/>';
 else if(status==='Alternate programme')draw+=badge('★','#bd7128');
 else if(status==='Camp')draw+=badge('▲','#ba6c25');
 else if(status==='Excursion')draw+=badge('E','#ba6c25');
 else if(status==='Music lesson')draw+=badge('♪');
 else if(status==='Sick bay')draw+=badge('+');
 else if(status.startsWith('Suspended'))draw=cross+badge(status.includes('External')?'E':'I');
 return `<svg class="attendance-symbol" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">${draw}</svg>`;
}
function markSelectedPresent(){const list=attendanceSessions().filter(l=>l.date===ui.rollDate),l=list.find(l=>l.periodId===ui.rollPeriod)||list[0];if(!l)return toast('Select a timetabled lesson first.',true);let count=0;for(const s of roster(byClass(ui.rollClass),l.date))if(!D.attendanceValue(state(),l,s.id).locked){writeAttendanceDraft(l,s.id,'Present');count++;}saveWorkDraft();render();toast(count+' students marked present. Protected entries were kept.');}
function marksOverall(id){return D.overall(state(),id,ui.markClass,ui.markYear,ui.markDraft,ui.statusDraft);}
function marksStatus(a,id){return D.assessmentStatus(a,id,ui.markDraft[a.id]||a.marks,ui.statusDraft[a.id]||a.statuses);}
