function assessmentsPage(){
 const tasks=markTasks(),c=byClass(ui.markClass),year=state().calendar.years.find(y=>y.id===ui.markYear),students=D.yearRoster(state(),ui.markClass,ui.markYear),mode=state().gradingModes[ui.markClass+'|'+ui.markYear]||'points';
 return heading('Evidence of learning','Yearly marksbook','Scores, submission status, class averages and overall progress.',button('Paste marks from Excel','paste-marks','','','clipboard')+button('Weightings','mark-weightings','','','settings')+button('Export marksbook','export-marks','','','download')+button('Create assessment','new-assessment','','primary','plus'))+`<div class="toolbar"><select id="marks-class" aria-label="Marksbook class">${classOptions(ui.markClass,true)}</select><select id="marks-year" aria-label="Marksbook school year">${yearOptions(ui.markYear)}</select>${badge(mode==='weighted'?'Weighted overall':'Points-based overall')}<span class="subtle">${tasks.length} tasks · ${students.length} students</span></div>`+(!c||!year||!tasks.length?empty('No assessments for this class and year','Create an assessment to begin.'):`<section class="panel"><div class="panel-head"><h2>${esc(c.name)} · ${esc(year.name)}</h2>${badge('A 75 · B 65 · C 50 · D 35 · E 15 · F <15')}</div><div class="table-wrap marks-scroll"><table class="marksbook"><thead><tr><th class="student-fixed" rowspan="2">Student</th>${tasks.map(a=>`<th colspan="2"><button class="assessment-heading" data-action="edit-assessment" data-id="${a.id}" title="${esc(a.title)}">${esc(a.title)}</button><small>${esc(fmt(a.due,{day:'numeric',month:'short'}))}${mode==='weighted'?' · '+a.weight+'% weight':''}</small></th>`).join('')}<th rowspan="2" class="overall-col">Overall<br>Percentage</th><th rowspan="2" class="overall-col">Overall<br>Grade</th></tr><tr>${tasks.map(a=>`<th>Score / ${a.max}</th><th class="percentage-col">%</th>`).join('')}</tr></thead><tbody>${students.map(s=>`<tr><th class="student-fixed" scope="row">${person(s)}</th>${tasks.map(a=>{const m=markValue(a,s.id),status=marksStatus(a,s.id),n=D.assessedValue(a,s.id,ui.markDraft[a.id]||a.marks,ui.statusDraft[a.id]||a.statuses);return `<td><input type="number" class="mark-input" id="mark-${a.id}-${s.id}" data-mark="${s.id}" data-assessment="${a.id}" min="0" max="${a.max}" step="any" value="${status==='Scored'?esc(m??''):''}"${status==='Not submitted'||status==='Exempt'?' disabled':''} aria-label="${esc(fullName(s)+' · '+a.title)}"><select class="mark-status" data-mark-status="${s.id}" data-assessment="${a.id}" aria-label="${esc(fullName(s)+' · '+a.title+' status')}">${D.ASSESSMENT_STATUSES.map(x=>opt(x,x,status)).join('')}</select></td><td class="percentage-col" id="percent-${a.id}-${s.id}">${Number.isFinite(n)?pct(n/a.max*100):'—'}</td>`;}).join('')}<td class="overall-col" id="overall-percent-${s.id}">${pct(marksOverall(s.id).percent)}</td><td class="overall-col"><span class="grade" id="overall-grade-${s.id}">${marksOverall(s.id).grade}</span></td></tr>`).join('')}</tbody><tfoot><tr><th class="student-fixed" scope="row">Class Average</th>${tasks.map(a=>`<td></td><td class="percentage-col" id="class-average-${a.id}">${pct(averageValue(a).percent)}</td>`).join('')}<td class="overall-col">—</td><td class="overall-col">—</td></tr></tfoot></table></div></section><div class="savebar"><span id="marks-save-label">${ui.markDirty?'Unsaved marks':'All marks saved'}</span><button class="button" data-action="save-marks">${icon('save')}Save marks</button></div>`)+`<p class="timeline-hint">Not marked and Exempt are excluded. Not submitted counts as zero. Class averages include recorded zeros. ${mode==='weighted'?'Overall uses configured task weightings, normalised across included tasks.':'Overall uses total earned marks ÷ maximum marks for included tasks.'} Grades use unrounded percentages.</p>`;
}
function ensureMarkDraft(a){ui.markDraft[a.id]??=D.clone(a.marks);ui.statusDraft[a.id]??=D.clone(a.statuses);}
function updateMarkInput(el){
 const a=state().assessments.find(x=>x.id===el.dataset.assessment),id=el.dataset.mark;ensureMarkDraft(a);ui.markDraft[a.id][id]=el.value;ui.statusDraft[a.id][id]=el.value===''?'Not marked':'Scored';ui.markDirty=true;const n=Number(el.value),valid=el.value!==''&&Number.isFinite(n)&&n>=0&&n<=a.max;el.setAttribute('aria-invalid',String(el.value!==''&&!valid));$('percent-'+a.id+'-'+id).textContent=valid?pct(n/a.max*100):'—';const selector=document.querySelector(`[data-mark-status="${id}"][data-assessment="${a.id}"]`);if(selector)selector.value=ui.statusDraft[a.id][id];updateMarkTotals(id);saveWorkDraft();
}
function updateMarkTotals(id){const total=marksOverall(id);$('overall-percent-'+id).textContent=pct(total.percent);$('overall-grade-'+id).textContent=total.grade;for(const a of markTasks())$('class-average-'+a.id).textContent=pct(averageValue(a).percent);$('marks-save-label').textContent='Unsaved marks';}
function saveMarks(){
 for(const input of document.querySelectorAll('.mark-input'))if(input.validity.badInput)throw new Error('Enter a valid score or leave it blank.');
 commit(s=>{for(const id of new Set([...Object.keys(ui.markDraft),...Object.keys(ui.statusDraft)])){const a=s.assessments.find(a=>a.id===id);if(!a)throw new Error('An assessment changed. Reload the marksbook.');const values=ui.markDraft[id]||a.marks,statuses=ui.statusDraft[id]||a.statuses,marks={};for(const [student,raw]of Object.entries(values)){const status=D.assessmentStatus(a,student,values,statuses);if(status!=='Scored'||raw===''||raw===null||raw===undefined)continue;const n=Number(raw);if(!Number.isFinite(n)||n<0||n>a.max)throw new Error('Every mark for '+a.title+' must be between 0 and '+a.max+'.');marks[student]=n;}a.marks=marks;a.statuses=D.clone(statuses);}},'Marksbook saved.');ui.markDraft={};ui.statusDraft={};ui.markDirty=false;clearWorkDraft('marks');render();
}
