 openDialog('Paste marks from Excel',form('mark-paste',ui.markClass+'|'+ui.markYear,`<p class="form-hint">Choose an assessment. Paste either one score per row in the displayed student order, or Student number / Name and Score in two columns. You can use Exempt, Not submitted or Not marked instead of a score. Changes are previewed before applying and still require Save marks.</p><label class="field">Assessment<select name="assessmentId" id="paste-assessment">${markTasks().map(a=>opt(a.id,a.title,'')).join('')}</select></label><label class="field">Pasted rows<textarea name="text" id="paste-mark-text" rows="10"></textarea></label>`,'Preview marks'),true);
