function preparePastedMarks(a,text){
 const rows=D.parseDelimited(text,undefined,true),roster=D.yearRoster(state(),a.classId,a.yearId),out=[],seen=new Set();
 const header=/^(student(?: number)?|name|score|marks?|status)$/i;if(rows[0]&&header.test(rows[0][0].trim())&&(rows[0].length===1||/^(score|marks?|status)$/i.test(rows[0][1]?.trim())))rows.shift();
 for(const [i,row]of rows.entries()){
  if(row.length>2)throw new Error('Row '+(i+1)+': paste one score column or two student/score columns.');let student,raw;if(row.length===1){student=roster[i];raw=row[0];}else{const key=row[0].trim().toLowerCase(),matches=roster.filter(s=>[s.code,fullName(s),s.firstName+' '+s.lastName].some(x=>x.toLowerCase()===key));if(matches.length!==1)throw new Error('Row '+(i+1)+': use a unique student number for unmatched or duplicate names.');student=matches[0];raw=row[1];}
  if(!student||seen.has(student.id))throw new Error('Row '+(i+1)+': too many rows or duplicate student.');seen.add(student.id);raw=String(raw??'').trim();const status=D.ASSESSMENT_STATUSES.find(x=>x.toLowerCase()===raw.toLowerCase());if(status&&status!=='Scored')out.push({studentId:student.id,status,score:''});else{const score=raw===''?'':Number(raw);if(score!==''&&(!Number.isFinite(score)||score<0||score>a.max))throw new Error('Row '+(i+1)+': score must be between 0 and '+a.max+'.');out.push({studentId:student.id,status:score===''?'Not marked':'Scored',score});}
 }if(!out.length)throw new Error('Paste at least one row.');return out;
}
