function exportMarks(){if(ui.markDirty)throw new Error('Save your marks before exporting.');const tasks=markTasks(),students=D.yearRoster(state(),ui.markClass,ui.markYear),rows=[['Student number','Student',...tasks.flatMap(a=>[a.title+' Score / '+a.max,a.title+' Status',a.title+' %']),'Overall Percentage','Overall Grade']];for(const s of students){const total=D.overall(state(),s.id,ui.markClass,ui.markYear);rows.push([s.code,fullName(s),...tasks.flatMap(a=>{const n=D.assessedValue(a,s.id);return[a.marks[s.id]??'',D.assessmentStatus(a,s.id),n===null?'':Number((n/a.max*100).toFixed(2))];}),total.percent===null?'':Number(total.percent.toFixed(2)),total.grade]);}rows.push(['','Class Average',...tasks.flatMap(a=>['','',pct(D.assessmentAverage(state(),a).percent)]),'','']);download('schooldesk-marksbook-'+today+'.csv',D.csv(rows),'text/csv;charset=utf-8');}

