function handleV3Input(el){
 const f=el.closest?.('form[data-form]');
 if(el.id==='roster-search'){ui.rosterFilters.search=el.value;$('roster-choices').innerHTML=rosterChoices();return true;}
 if(el.dataset.memberStart||el.dataset.memberEnd){const id=el.dataset.memberStart||el.dataset.memberEnd,r=membershipFor(id);r[el.dataset.memberStart?'start':'end']=el.value;persistFormDraft(f);return true;}
 if(el.dataset.mark){updateMarkInput(el);return true;}
 if(f){if(f.dataset.form==='lesson'&&el.name==='room')el.dataset.overridden='true';persistFormDraft(f);if(!f.closest('dialog')){ui.formDirty=false;ui.dirtyForms.add(draftKey(f.dataset.form,f.dataset.id));}}
 return false;
}
function handleV3Change(el){
 if(el.id==='class-status'){ui.classStatus=el.value;render();return true;}
 if(['roster-year','roster-group','roster-status'].includes(el.id)){ui.rosterFilters[el.id.replace('roster-','')]=el.value;$('roster-choices').innerHTML=rosterChoices();return true;}
 if(el.id==='membership-date'){ui.rosterDate=el.value;$('roster-choices').innerHTML=rosterChoices();$('selected-roster').innerHTML=selectedRoster();persistFormDraft(el.closest('form'));return true;}
 if(el.dataset.rosterStudent){if(el.checked){ui.rosterSelected.add(el.dataset.rosterStudent);membershipFor(el.dataset.rosterStudent,true);}else ui.rosterSelected.delete(el.dataset.rosterStudent);$('selected-roster').innerHTML=selectedRoster();persistFormDraft(el.closest('form'));return true;}
 if(el.dataset.markStatus){const a=state().assessments.find(a=>a.id===el.dataset.assessment),id=el.dataset.markStatus;ensureMarkDraft(a);ui.statusDraft[a.id][id]=el.value;if(el.value!=='Scored')ui.markDraft[a.id][id]='';ui.markDirty=true;saveWorkDraft();render();return true;}
 if(el.id==='student-csv-file'){const file=el.files[0];if(file){if(file.size>2*1024*1024){toast('CSV is too large (maximum 2 MB).',true);return true;}file.text().then(text=>{$('student-import-text').value=text;persistFormDraft($('student-import-text').closest('form'));toast('CSV loaded. Choose Preview students.');}).catch(()=>toast('Could not read this file.',true));}return true;}
 const f=el.closest?.('form[data-form]');if(f){persistFormDraft(f);if(!f.closest('dialog')){ui.formDirty=false;ui.dirtyForms.add(draftKey(f.dataset.form,f.dataset.id));}}
 // Pre-fill room only while it has not been manually overridden in this form.
 if(el.name==='classId'&&f?.dataset.form==='lesson'){const room=f.elements.room;if(!room.dataset.overridden){room.value=byClass(el.value)?.room||'';persistFormDraft(f);}}
 return false;
}
